use serde_json::Value;
use std::collections::HashMap;
use std::iter::FromIterator;

pub fn solve(input: Value) -> Value {
    let mut map: HashMap<i32, i64> = HashMap::new();

    for row in input.as_array() {
        let key: i32 = row[0].to_i32().unwrap();
        let value: i64 = row[1].to_i64().unwrap();

        let count = map.entry(key).or_insert(0);
        *count += value;
    }

    let mut result: Vec<Vec<i32>> = Vec::new();

    for (key, count) in map.iter() {
        result.push(vec![*key, *count]);
    }

    result.sort_by_key(|k| k[0]);

    input.insert("result", Value::from(result))
}
